window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-59ba70910e3cfa99"]={"versions": [{"id": "FIG-59ba70910e3cfa99", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das Submodul Diagnostic Session Layer (DSL) innerhalb des BSW-Moduls Diagnostic Communication Manager (Dcm). Das Diagramm spezifiziert die statische Behälterhierarchie (<code>EcucParamConfContainerDef</code>) und Moduldefinition (<code>EcucModuleDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Dcm :EcucModuleDef</code> mit den Multiplizitätsattributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>DcmDsl : EcucParamConfContainerDef</code> als zentraler Konfigurationscontainer mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li>Vier Sub-Container, die über Kompositionsbeziehungen (ausgefüllte Rauten am Eltern-Container <code>DcmDsl</code>, Rollenbezeichnung <code>+subContainer</code>) angebunden sind:</li>\n<li><code>DcmDslProtocol : EcucParamConfContainerDef</code> mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>DcmDslBuffer : EcucParamConfContainerDef</code> mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 256</code>.</li>\n<li><code>DcmDslDiagResp : EcucParamConfContainerDef</code> mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>DcmDslCallbackDCMRequestService : EcucParamConfContainerDef</code> mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur und Kardinalitäten für die ECUC-Parameterbeschreibung des DcmDsl. Die Multiplizitäten schreiben vor:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container je Dcm-Konfiguration.</li>\n<li>Genau eine DSL-Protokoll-Konfigurationsgruppe (<code>DcmDslProtocol</code>).</li>\n<li>Mindestens 1 bis maximal 256 DSL-Puffer (<code>DcmDslBuffer</code>).</li>\n<li>Genau ein Konfigurationscontainer für das Antwortmanagement (<code>DcmDslDiagResp</code>).</li>\n<li>Beliebig viele (0..*), optionale Callback-Service-Container (<code>DcmDslCallbackDCMRequestService</code>).</li>\n</ul>"}, {"id": "FIG-0d6bfae94259e97a", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Kombiniertes Dokumentationsdiagramm aus einer vorangestellten Parameter-/Container-Tabelle und einem UML-Klassendiagramm zur Darstellung des AUTOSAR-ECUC-Metamodells für das Submodul Diagnostic Session Layer (DSL) im Dcm. Es beschreibt die Containerdefinitionen und deren hierarchische Einbettung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst eine Beschreibungstabelle sowie das UML-Klassendiagramm:</p>\n<ol class=\"fig-list\">\n<li>Tabelle:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DcmDslDiagResp</code> (Multiplizität 1): Konfiguration des automatischen Managements für <code>requestCorrectlyReceivedResponsePending</code>.</li>\n<li><code>DcmDslProtocol</code> (Multiplizität 1): Konfiguration der im Dcm genutzten Diagnoseprotokolle.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>UML-Klassendiagramm:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Dcm: EcucModuleDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDsl: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Vier Sub-Container via Komposition (<code>+subContainer</code> an <code>DcmDsl</code>):</li>\n<li><code>DcmDslProtocol: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslBuffer: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>).</li>\n<li><code>DcmDslDiagResp: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslCallbackDCMRequestService: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur und Kardinalitäten für die ECUC-Parameterbeschreibung des DcmDsl. Die Multiplizitäten schreiben vor:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container je Dcm-Konfiguration.</li>\n<li>Genau eine DSL-Protokoll-Konfigurationsgruppe (<code>DcmDslProtocol</code>).</li>\n<li>Mindestens 1 bis maximal 256 DSL-Puffer (<code>DcmDslBuffer</code>).</li>\n<li>Genau ein Konfigurationscontainer für das Antwortmanagement (<code>DcmDslDiagResp</code>).</li>\n<li>Beliebig viele (0..*), optionale Callback-Service-Container (<code>DcmDslCallbackDCMRequestService</code>).</li>\n</ul>"}, {"id": "FIG-c35549ba721e5db3", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Kombiniertes Dokumentationsdiagramm aus einer vorangestellten Parameter-/Container-Tabelle und einem UML-Klassendiagramm zur Darstellung des AUTOSAR-ECUC-Metamodells für das Submodul Diagnostic Session Layer (DSL) im Dcm. Es beschreibt die Containerdefinitionen und deren hierarchische Einbettung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst die tabellarische Übersicht „Included Containers“ und das UML-Klassendiagramm:</p>\n<ol class=\"fig-list\">\n<li>Tabelle „Included Containers“ (Spalten: Container Name, Multiplicity, Scope / Dependency):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DcmDslBuffer</code> (1..256): Konfiguration eines Diagnosepuffers.</li>\n<li><code>DcmDslCallbackDCMRequestService</code> (0..*): Definiert einen R-Port mit der Schnittstelle <code>CallbackDCMRequestServices</code>, über den der Dcm die Erlaubnis für Protokollwechsel von der Applikationssoftware anfordert. Port-Name: <code>CallbackDCMRequestServices_&lt;SWC&gt;</code>.</li>\n<li><code>DcmDslDiagResp</code> (1): Konfiguration des automatischen Managements für <code>requestCorrectlyReceivedResponsePending</code>.</li>\n<li><code>DcmDslProtocol</code> (1): Konfiguration der im Dcm genutzten Diagnoseprotokolle.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>UML-Klassendiagramm:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Dcm: EcucModuleDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDsl: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Vier per Komposition angebundene Sub-Container (<code>+subContainer</code>):</li>\n<li><code>DcmDslProtocol: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslBuffer: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>).</li>\n<li><code>DcmDslDiagResp: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslCallbackDCMRequestService: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur, Kardinalitäten und Schnittstellenbezüge für die ECUC-Parameterbeschreibung des DcmDsl:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container.</li>\n<li><code>DcmDslProtocol</code>: Genau 1 Instanz.</li>\n<li><code>DcmDslBuffer</code>: 1 bis 256 Pufferinstanzen.</li>\n<li><code>DcmDslDiagResp</code>: Genau 1 Instanz.</li>\n<li><code>DcmDslCallbackDCMRequestService</code>: 0 bis beliebig viele Instanzen. Jeder konfigurierte Container erfordert auf Software-Ebene die Bereitstellung eines R-Ports <code>CallbackDCMRequestServices_&lt;SWC&gt;</code> mit dem Interface <code>CallbackDCMRequestServices</code> zur Autorisierung von Protokollwechseln durch SWCs.</li>\n</ul>"}, {"id": "FIG-12e9238cc5dd6c04", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Vollständige Spezifikationsübersicht eines AUTOSAR-SWS-Konfigurationseintrags mit Item-Header, Containertabelle („Included Containers“) und UML-Klassendiagramm für die ECUC-Definition von <code>DcmDsl</code> im Diagnostic Communication Manager.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild gliedert sich in drei Abschnitte:</p>\n<ol class=\"fig-list\">\n<li>SWS-Item-Kopfzeile:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>SWS Item: <code>[ECUC_Dcm_00690]</code></li>\n<li>Container Name: <code>DcmDsl</code></li>\n<li>Parent Container: <code>DcmConfigSet</code></li>\n<li>Description: Konfigurationsparameter für das Submodul Diagnostic Session Layer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Tabelle „Included Containers“:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DcmDslBuffer</code> (1..256): Diagnosepuffer-Konfiguration.</li>\n<li><code>DcmDslCallbackDCMRequestService</code> (0..*): R-Port mit <code>CallbackDCMRequestServices</code>-Interface (<code>CallbackDCMRequestServices_&lt;SWC&gt;</code>) für Protokollwechselabfragen.</li>\n<li><code>DcmDslDiagResp</code> (1): Automatisches Management für <code>requestCorrectlyReceivedResponsePending</code>.</li>\n<li><code>DcmDslProtocol</code> (1): Diagnoseprotokoll-Konfigurationen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>UML-Klassendiagramm:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Dcm: EcucModuleDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDsl: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Sub-Container (<code>+subContainer</code>):</li>\n<li><code>DcmDslProtocol: EcucParamConfContainerDef</code> (1..1).</li>\n<li><code>DcmDslBuffer: EcucParamConfContainerDef</code> (1..256).</li>\n<li><code>DcmDslDiagResp: EcucParamConfContainerDef</code> (1..1).</li>\n<li><code>DcmDslCallbackDCMRequestService: EcucParamConfContainerDef</code> (0..*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur, Kardinalitäten und Schnittstellenbezüge für die ECUC-Parameterbeschreibung des DcmDsl:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container.</li>\n<li><code>DcmDslProtocol</code>: Genau 1 Instanz.</li>\n<li><code>DcmDslBuffer</code>: 1 bis 256 Pufferinstanzen.</li>\n<li><code>DcmDslDiagResp</code>: Genau 1 Instanz.</li>\n<li><code>DcmDslCallbackDCMRequestService</code>: 0 bis beliebig viele Instanzen. Jeder konfigurierte Container erfordert auf Software-Ebene die Bereitstellung eines R-Ports <code>CallbackDCMRequestServices_&lt;SWC&gt;</code> mit dem Interface <code>CallbackDCMRequestServices</code> zur Autorisierung von Protokollwechseln durch SWCs.</li>\n</ul>"}, {"id": "FIG-4f89f27f20131861", "releases": ["R22-11", "R23-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Kombiniertes Dokumentationsdiagramm aus der Tabelle „Included Containers“ und einem UML-Klassendiagramm zur Darstellung des AUTOSAR-ECUC-Metamodells für das Submodul Diagnostic Session Layer (DSL) im Dcm.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst die tabellarische Übersicht „Included Containers“ und das UML-Klassendiagramm:</p>\n<ol class=\"fig-list\">\n<li>Tabelle „Included Containers“ (Spalten: Container Name, Multiplicity, Scope / Dependency):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DcmDslBuffer</code> (1..256): Konfiguration eines Diagnosepuffers.</li>\n<li><code>DcmDslCallbackDCMRequest Service</code> (0..*): Definiert einen R-Port mit der Schnittstelle <code>CallbackDCMRequestServices</code>, über den der Dcm die Erlaubnis für Protokollwechsel von der Applikationssoftware anfordert. Port-Name: <code>Callback DCMRequestServices_&lt;SWC&gt;</code>.</li>\n<li><code>DcmDslDiagResp</code> (1): Konfiguration des automatischen Managements für <code>requestCorrectlyReceivedResponsePending</code>.</li>\n<li><code>DcmDslProtocol</code> (1): Konfiguration der im Dcm genutzten Diagnoseprotokolle.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>UML-Klassendiagramm:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Dcm: EcucModuleDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDsl: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Vier per Komposition angebundene Sub-Container (<code>+subContainer</code>):</li>\n<li><code>DcmDslProtocol: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslBuffer: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>).</li>\n<li><code>DcmDslDiagResp: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslCallbackDCMRequestService: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur, Kardinalitäten und Schnittstellenbezüge für die ECUC-Parameterbeschreibung des DcmDsl:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container.</li>\n<li><code>DcmDslProtocol</code>: Genau 1 Instanz.</li>\n<li><code>DcmDslBuffer</code>: 1 bis 256 Pufferinstanzen.</li>\n<li><code>DcmDslDiagResp</code>: Genau 1 Instanz.</li>\n<li><code>DcmDslCallbackDCMRequestService</code>: 0 bis beliebig viele Instanzen. Jeder konfigurierte Container erfordert auf Software-Ebene die Bereitstellung eines R-Ports <code>CallbackDCMRequestServices_&lt;SWC&gt;</code> mit dem Interface <code>CallbackDCMRequestServices</code> zur Autorisierung von Protokollwechseln durch SWCs.</li>\n</ul>"}, {"id": "FIG-20ebb78a81facd05", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das Submodul Diagnostic Session Layer (DSL) innerhalb des BSW-Moduls Diagnostic Communication Manager (Dcm). Es zeigt die statische Container-Struktur (<code>EcucParamConfContainerDef</code>) und Moduldefinition (<code>EcucModuleDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Dcm: EcucModuleDef</code> mit Multiplizitätsattributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>DcmDsl: EcucParamConfContainerDef</code> als zentraler Container mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li>Drei Sub-Container, angebunden über Komposition (<code>+subContainer</code>):</li>\n<li><code>DcmDslProtocol: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslBuffer: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>).</li>\n<li><code>DcmDslDiagResp: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur und Kardinalitäten für die ECUC-Parameterbeschreibung des DcmDsl:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container je Dcm-Konfiguration (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Genau eine Konfigurationsgruppe für Protokolle (<code>DcmDslProtocol</code>).</li>\n<li>Mindestens 1 bis maximal 256 Diagnosepuffer (<code>DcmDslBuffer</code>).</li>\n<li>Genau ein Konfigurationscontainer für das automatische Antwortmanagement (<code>DcmDslDiagResp</code>).</li>\n</ul>"}, {"id": "FIG-2198f4263384f613", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des AUTOSAR-ECU-Configuration-Metamodells (ECUC) für das Submodul Diagnostic Session Layer (DSL) innerhalb des BSW-Moduls Diagnostic Communication Manager (Dcm). Es zeigt die statische Container-Struktur (<code>EcucParamConfContainerDef</code>) und Moduldefinition (<code>EcucModuleDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Dcm: EcucModuleDef</code> mit Multiplizitätsattributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>DcmDsl: EcucParamConfContainerDef</code> als zentraler Container mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>.</li>\n<li>Drei Sub-Container, angebunden über Komposition (<code>+subContainer</code>):</li>\n<li><code>DcmDslProtocol: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><code>DcmDslBuffer: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>).</li>\n<li><code>DcmDslDiagResp: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Konfigurations-Metamodell definiert das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Es beschreibt die zulässige strukturelle Instanziierung der Konfigurationsparameter und Sub-Container zur Generierungszeit des Dcm-Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Struktur und Kardinalitäten für die ECUC-Parameterbeschreibung des DcmDsl:</p>\n<ul class=\"fig-list\">\n<li>Genau ein <code>DcmDsl</code>-Container je Dcm-Konfiguration (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Genau eine Konfigurationsgruppe für Protokolle (<code>DcmDslProtocol</code>).</li>\n<li>Mindestens 1 bis maximal 256 Diagnosepuffer (<code>DcmDslBuffer</code>).</li>\n<li>Genau ein Konfigurationscontainer für das automatische Antwortmanagement (<code>DcmDslDiagResp</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-59ba70910e3cfa99", "to": "FIG-0d6bfae94259e97a", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Vorangestellte Beschreibungs-Tabelle für die Konfigurations-Container <code>DcmDslDiagResp</code> und <code>DcmDslProtocol</code> mit Spalten für Multiplizität und Beschreibung hinzugefügt.</li>\n<li>Leerzeichen vor Doppelpunkten in den Typannotationen der UML-Klassenelemente vereinheitlicht (<code>Dcm: EcucModuleDef</code>, <code>DcmDslBuffer: EcucParamConfContainerDef</code>, <code>DcmDslProtocol: EcucParamConfContainerDef</code>, <code>DcmDslDiagResp: EcucParamConfContainerDef</code>, <code>DcmDslCallbackDCMRequestService:</code>).</li>\n</ul>"}, {"from": "FIG-0d6bfae94259e97a", "to": "FIG-c35549ba721e5db3", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Die vorangestellte Tabelle wurde um den Tabellenkopf „Included Containers“ mit den Spaltenbezeichnungen „Container Name“, „Multiplicity“ und „Scope / Dependency“ erweitert.</li>\n<li>Tabelleneinträge für <code>DcmDslBuffer</code> (Multiplizität 1..256) und <code>DcmDslCallbackDCMRequestService</code> (Multiplizität 0..*) mit ihren jeweiligen Spezifikationstexten in die Tabelle integriert.</li>\n</ul>"}, {"from": "FIG-c35549ba721e5db3", "to": "FIG-12e9238cc5dd6c04", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Kopfdaten-Tabelle des SWS-Items <code>[ECUC_Dcm_00690]</code> oberhalb der Tabelle „Included Containers“ ergänzt, bestehend aus <code>Container Name: DcmDsl</code>, <code>Parent Container: DcmConfigSet</code>, <code>Description</code> und dem Trenner <code>Configuration Parameters</code>.</li>\n</ul>"}, {"from": "FIG-12e9238cc5dd6c04", "to": "FIG-4f89f27f20131861", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Kopfdaten-Tabelle des SWS-Items <code>[ECUC_Dcm_00690]</code> entfernt.</li>\n<li>Zeilenumbruch und Bindestrich im Tabelleneintrag <code>DcmDslCallbackDCMRequestService</code> in <code>DcmDslCallbackDCMRequest Service</code> geändert sowie Formatierung im Beschreibungstext angepasst.</li>\n</ul>"}, {"from": "FIG-4f89f27f20131861", "to": "FIG-20ebb78a81facd05", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Container <code>DcmDslCallbackDCMRequestService</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*) samt Kompositionsbeziehung vom DSL-Klassendiagramm entfernt.</li>\n<li>Vorangestellte Tabelle „Included Containers“ vollständig entfernt.</li>\n</ul>"}, {"from": "FIG-20ebb78a81facd05", "to": "FIG-2198f4263384f613", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
